def genericFormalFiber (A T : Type u) [CommRing A] [CommRing T] (ι : A →+* T) :
    Set (Ideal T) :=
  {P | P.IsPrime ∧ Ideal.comap ι P = ⊥}

def NSubring (T : Type u) [CommRing T] : Type u :=
  {R : Subring T //
    Nonempty R ∧
      (∀ Q : Ideal T, Q.IsPrime → True) ∧
        (∀ t : T, t ≠ 0 → ∀ P : Ideal T, P.IsPrime → True)}

